import { formatDate } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { AlertController, ModalController } from '@ionic/angular';
import { CalendarMode, Step } from 'ionic2-calendar/calendar';
import { UploadService } from 'src/app/services/emis/upload.service';
import { UserService } from 'src/app/services/emis/user.service';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { ClassSecListPage } from '../class-sec-list/class-sec-list.page';

@Component({
  selector: 'app-view-calendar',
  templateUrl: './view-calendar.page.html',
  styleUrls: ['./view-calendar.page.scss'],
})
export class ViewCalendarPage implements OnInit {

  eventSource = [];
  viewTitle: string;
  isToday: boolean;

  public colors: any = {
    red: {
      primary: '#ad2121',
      secondary: '#FAE3E3'
    },
  }

  calendar = {
    mode: 'month' as CalendarMode,
    step: 30 as Step,
    currentDate: new Date(),
    dateFormatter: {
      formatMonthViewDay: function (date: Date) {
        return date.getDate().toString();
      },
      formatMonthViewDayHeader: function (date: Date) {
        return 'MonMH';
      },
      formatMonthViewTitle: function (date: Date) {
        return 'testMT';
      },
      formatWeekViewDayHeader: function (date: Date) {
        return 'MonWH';
      },
      formatWeekViewTitle: function (date: Date) {
        return 'testWT';
      },
      formatDayViewTitle: function (date: Date) {
        return 'testDT';
      }
    }
  };

  selectedDate: Date;
  schoolClassData: any;
  schoolId: any;
  routeData: any;
  slot1: boolean;
  slot2: boolean;
  eventOn: boolean;
  filter: any[] = [];
  colorOnchange: boolean;
  colorOnchange1: boolean;
  holiday: boolean;
  arrayFinal: any[] = [];
  username: any;
  finalDate: Date;
  slot: any;
  notes: boolean;

  date = new Date();
  notes1: boolean;
  tomorrow: Date;
  schoolAvaData: any[] = [];
  titles1: any;
  titles2: string;
  titles: string;
  item: any;
  startdate: any;
  enddate: any;
  statusMode: any;
  cycle: any;
  eventstartdate: any;
  eventenddate: any;

  constructor(
    private alertCtrl: AlertController,
    private modalCtrl: ModalController,
    private userService: UserService,
    private route: ActivatedRoute,
    private router: Router,
    private usersessionService: UserSessionService,

  ) {
    this.username = this.usersessionService.emis_username();
  }

  ngOnInit() {
  }

  ionViewDidEnter() {

    this.routeData = this.route.snapshot;
    this.schoolId = this.routeData.queryParams.schoolId;
    this.slot = this.routeData.queryParams.slot;
    this.item = this.routeData.queryParams.item;
    this.startdate = this.routeData.queryParams.startdate;
    this.enddate = this.routeData.queryParams.enddate;
    this.eventstartdate = this.routeData.queryParams.eventstartdate;
    this.eventenddate = this.routeData.queryParams.eventenddate;

    this.statusMode = this.routeData.queryParams.statusMode;
    this.cycle = this.routeData.queryParams.cycle;
    this.eventOn = false
    this.holiday = false
    this.clear()
    this.viewData()

    var tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    this.tomorrow = tomorrow

  }

  // Calendar event was clicked
  async onEventSelected(event) {

    // Use Angular date pipe for conversion
    let start = formatDate(9, 'medium', '');
    let end = formatDate(1, 'medium', '');

    const alert = await this.alertCtrl.create({
      header: event.title,
      subHeader: event.desc,
      message: 'From: ' + start + '<br><br>To: ' + end,
      buttons: ['OK'],
    });
    alert.present();
  }

  removeEvents() {
    this.eventSource = [];
  }

  viewData() {
    this.schoolClassData = []
    this.userService.getViewSlot(this.username).subscribe((response) => {

      let filter = response.result.filter(
        (item: any) => item.planning_date != null || item.holiday == 1 || item.session2 != null || item.session1 != null
      );
      this.schoolClassData.push(filter)

      let filter1 = response.result.filter(
        (item: any) => item.holiday == 0 && (item.session2 == null || item.session1 == null)
      );
      this.schoolAvaData.push(filter1)


      this.createEvents()
    })
  }

  onViewTitleChanged(title) {
    this.viewTitle = title;
  }

  createEvents() {
    var events = [];
    for (var i = 0; i < this.schoolClassData[0].length; i += 1) {
     
      let array = this.schoolClassData[0]

      var date = new Date(array[i].date);
      var startTime;
      var endTime;
      startTime = new Date(
        Date.UTC(
          date.getUTCFullYear(),
          date.getUTCMonth(),
          date.getUTCDate(),
          date.getHours() - 2,
          date.getMinutes()
        )
      );

      endTime = new Date(
        Date.UTC(
          date.getUTCFullYear(),
          date.getUTCMonth(),
          date.getUTCDate(),
          date.getHours() + 5,
          date.getMinutes()

        )
      );
  
       if (array[i].holiday == 0 && array[i].session1 == null && array[i].session2 == null) {
        this.titles = 'No Event'
      } else {
        this.titles = array[i].date
      }

      if (array[i].holiday == 1) {
        this.titles = 'Holiday'
      } else {
        this.titles = array[i].date
      }
      events.push({
        title: this.titles,
        startTime: startTime,
        endTime: endTime,
        allDay: false,
        color: '#46c4f3'
      });
    }
    this.eventSource = events;
  }

  onCurrentDateChanged(event: Date) {
    this.titles1 =''
    this.titles2 =''
    var today = new Date();
    if (event < new Date()) {
      this.notes = true
    } else {
      if (event < new Date(new Date().setDate(today.getDate() + 60))) {
        this.notes = false
        this.notes1 = false
      } else {
        this.notes = false
        this.notes1 = true
      }
    }

    this.slot1 = false;
    this.slot2 = false;
    this.filter = []
    this.eventOn = true
    this.holiday = true
    this.colorOnchange = false
    this.colorOnchange1 = false
    this.finalDate = event

    var date = new Date(event),
      mnth = ("0" + (date.getMonth() + 1)).slice(-2),
      day = ("0" + date.getDate()).slice(-2);

    let filter
    filter = this.schoolClassData[0].filter(
      (item: any) => item.date == date.getFullYear() + '-' + mnth + '-' + day
    );
    this.filter.push(filter[0])

    if (this.filter[0] != undefined) {
      if (this.filter[0].session1 == null) {
        this.titles1 = 'No Event'
      } else {
        let tit1;
        tit1 = this.filter[0].Session1_program_type
        this.titles1 = tit1 + '-' + this.filter[0].SchlName1
      }
 
      if (this.filter[0].session2 == null) {
        this.titles2 = 'No Event'
      } else {
        let tit2;
        tit2 = this.filter[0].Session2_program_type
        this.titles2 = tit2 + '-' + this.filter[0].SchlName2
      }

      if (this.filter[0].holiday == 1) {
        this.holiday = false;
      } else {
        this.holiday = true;
      }

      if (this.filter[0].session1 == null) {
        this.slot1 = false;
      } else {
        this.slot1 = true;
      }

      if (this.filter[0].session2 == null) {
        this.slot2 = false;
      } else {
        this.slot2 = true;
      }

      if (this.filter[0].session1 == null && this.filter[0].session2 == null) {
        this.slot1 = false;
        this.slot2 = false;
      } else {
      }

    } else {
      this.titles1 = 'No Event'
      this.titles2 = 'No Event'
    }
    
  }

  clear() {
    this.arrayFinal = []
  }

  goBack() {
    this.router.navigate(['/tabs/school-schedule'], { queryParams: { "item": this.item, "startdate": this.startdate, "enddate": this.enddate,"eventstartdate": this.eventstartdate, "eventenddate": this.eventenddate, 'statusMode': this.statusMode, 'cycle': this.cycle} });
    // this.router.navigate(['/tabs/school-schedule'], { queryParams: { "item": this.item, "startdate": this.startdate, "enddate": this.enddate, 'statusMode': this.statusMode, 'cycle': this.cycle} });
  }

}

